"use strict";
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");
const crypto = require("node:crypto");
const root = path.resolve(__dirname, "../..");
const policy = Object.freeze({ seeds: Object.freeze([88221, 88222]), sample: 0.72, safety: 1400, invitationIndex: 0, decisions: "secure/zone/first legal" });
const sha256 = value => crypto.createHash("sha256").update(typeof value === "string" || Buffer.isBuffer(value) ? value : JSON.stringify(value)).digest("hex");

// Current index order, browser globals, memory UI; the UI boot controller is
// excluded as in the career VM. No production owner is wrapped or replaced.
function createContext() {
  const index = fs.readFileSync(path.join(root, "index.html"), "utf8");
  const files = [...index.matchAll(/<script src="([^"]+)"/g)].map(row => row[1]).filter(file => file !== "application-controller.js");
  const nodes = new Map(), storage = new Map();
  const classList = () => ({ add() {}, remove() {}, toggle() {}, contains() { return false; } });
  const context = vm.createContext({
    console: { log() {}, warn() {}, error: console.error },
    document: {
      body: { classList: classList() },
      getElementById(id) {
        if (!nodes.has(id)) nodes.set(id, { id, innerHTML: "", textContent: "", value: "", style: {}, dataset: {}, disabled: false,
          classList: classList(), focus() {}, setAttribute() {}, removeAttribute() {}, querySelectorAll() { return []; } });
        return nodes.get(id);
      },
      querySelector() { return null; }, querySelectorAll() { return []; }
    },
    localStorage: { setItem(k, v) { storage.set(k, v); }, getItem(k) { return storage.get(k) || null; }, removeItem(k) { storage.delete(k); } },
    window: { setTimeout() { return 1; }, clearTimeout() {} }
  });
  const sourceHashes = { "index.html": sha256(Buffer.from(index)) };
  for (const file of files) {
    const source = fs.readFileSync(path.join(root, file)); sourceHashes[file] = sha256(source);
    vm.runInContext(source.toString("utf8"), context, { filename: file });
  }
  const run = source => vm.runInContext(source, context);
  const json = source => JSON.parse(run(`JSON.stringify(${source})`));
  return { context, files, sourceHashes, run, json };
}

function playCanonicalMatch(seed) {
  if (!policy.seeds.includes(seed)) throw new Error("Only the two reviewed regression seeds are supported");
  const h = createContext(); h.context.contractSeed = seed;
  h.run(`
    function contractCopy(value) { return JSON.parse(JSON.stringify(value)); }
    function contractAbilities(p = player) {
      return {baseballSkills:p.baseballSkills,ballSense:p.ballSense,observe:p.observe,fitness:p.fitness,
        instinct:p.instinct,discipline:p.discipline,pressure:p.pressure,body:p.body,
        baseballExperience:p.baseballExperience,capabilityState:p.capabilityState};
    }
    function contractState() {
      const side = getHighSchoolPlayerTeamSide(m), roster = m.rosters[side];
      return {inning:m.inning,half:m.half,outs:m.outs,scores:{...m.scores},runners:m.runners.slice(),
        phase:m.simulationPhase,domain:m.currentDomain,currentMomentId:m.currentMomentId,
        playerSide:side,offenseTeam:m.offenseTeam,currentBatter:m.currentBatter,
        actualBatter:getHighSchoolMatchLineupBatter(m,m.offenseTeam)?.id,
        status:m.playerLineupStatus,entryCompleted:m.playerEntryCompleted,slot:m.playerLineupSlot,
        assignment:m.playerFieldingAssignment,playerInLineup:roster.lineup.some(a=>a.id==='player'),
        playerOnBench:roster.bench.some(a=>a.id==='player'),actualSS:TeamRosterFoundation.getCurrentDefender(roster,'SS')?.id,
        completedIds:m.completedMoments.map(x=>x.id),logCount:m.simulationLog.length,
        integrity:getHighSchoolMatchStateIntegrityIssues(m)};
    }
    stopHighSchoolMatchPlayback(); pendingYouthSeasonOutcome = null; isTransitioning = false;
    player = createInitialPlayer('2.2.2 測試球員');
    applyDebugBookmarkCharacterProfile(player);
    settleHighSchoolEntryCapability(player, {originType:'test-fixture'});
    applyCanonicalPositionProfile(player, '內野手', ['外野手']);
    globalThis.contractOriginalAbilities = JSON.stringify(contractAbilities());
    applyCanonicalPositionProfile(player, '游擊手', ['外野手']);
    globalThis.contractInvitations = generateSchoolInvitationSet(player);
    globalThis.contractSchool = contractInvitations.invitations[0];
    globalThis.contractSelection = finalizeSchoolInvitationSelection(player, contractSchool.schoolId);
    globalThis.contractEntered = completeHighSchoolEntry({source:'b1-normal-entry-proof'});
    player.highSchoolStep = 5; applyHighSchoolRoleState('starter');
    pendingHighSchoolMatchSimulationSeed = contractSeed;
    globalThis.contractFixture = contractCopy(player);
    globalThis.m = prepareHighSchoolYearOneMatch();
    globalThis.contractInitial = contractCopy(m);
    globalThis.contractEntry = {accepted:contractEntered,selection:contractSelection,schoolId:contractSchool.schoolId,
      invitationIndex:0,age:player.age,primaryPosition:player.primaryPosition,
      invitationValidation:validateSchoolInvitationSet(player.schoolInvitationState),
      capabilityValidation:validateHighSchoolEntryCapability(player),
      abilitiesUnchanged:contractOriginalAbilities===JSON.stringify(contractAbilities()),
      pendingSeedAfterPrepare:pendingHighSchoolMatchSimulationSeed,
      globals:{playingTime:typeof PlayingTimeGameExposure,roster:typeof TeamRosterFoundation,
        entryRoster:typeof HighSchoolEntryRosterContext,record:typeof MatchGameRecord},initialState:contractState()};
    globalThis.contractSteps = []; globalThis.contractDecisions = []; globalThis.contractDuplicates = [];
    globalThis.contractSafety = 0;
    while (!m.completed && contractSafety < 1400) {
      contractSafety += 1;
      const before = contractState(), logBefore = m.simulationLog.length, countBefore = m.completedMoments.length;
      const visible = isHighSchoolMatchDecisionVisible(m), row = {tick:contractSafety,mode:visible?'decision':'playback',before};
      if (visible) {
        const choices = getHighSchoolYearOneMatchMomentChoices(m);
        const choice = choices.find(c=>c.matchDecision==='secure'||c.matchDecision==='zone') || choices[0];
        if (!choice) throw new Error('No legal choice under reviewed policy');
        const d = {tick:contractSafety,before:contractCopy(before),legalChoices:contractCopy(choices),choice:contractCopy(choice),sample:0.72};
        d.returned = resolveHighSchoolYearOneMatch(choice.matchDecision, choice.matchMomentId, ()=>0.72);
        d.after = contractState(); d.newEvents = contractCopy(m.simulationLog.slice(logBefore));
        d.newCompleted = contractCopy(m.completedMoments.slice(countBefore)); contractDecisions.push(d);
        const unchanged = JSON.stringify(player);
        const duplicate = resolveHighSchoolYearOneMatch(choice.matchDecision, choice.matchMomentId, ()=>0.72);
        contractDuplicates.push({momentId:choice.matchMomentId,decision:choice.matchDecision,returned:duplicate,fullPlayerUnchanged:unchanged===JSON.stringify(player)});
      } else advanceHighSchoolMatchPlaybackStep(m);
      row.after = contractState(); row.newEvents = contractCopy(m.simulationLog.slice(logBefore)); contractSteps.push(row);
    }
    globalThis.contractFinalPlayer = contractCopy(player); globalThis.contractFinalState = contractState();
    globalThis.contractCore = JSON.stringify(player);
    globalThis.contractRepeats = [settleHighSchoolYearOneMatch(m,'zone'),settleHighSchoolYearOneMatch(m,'zone'),finishHighSchoolMatchBySimulation(m)];
    globalThis.contractRepeatUnchanged = contractCore===JSON.stringify(player);
    globalThis.contractRestored = normalizeSave(contractCopy(player));
    globalThis.contractRecordIntegrity = MatchGameRecord.assertIntegrity(m.gameRecord);
    globalThis.contractSaveRecordIntegrity = MatchGameRecord.assertIntegrity(contractRestored.highSchoolMatch.gameRecord);
    globalThis.contractActualExposure = deriveHighSchoolMatchActualExposure(m);
    globalThis.contractReadUnchanged = contractCore===JSON.stringify(player);
  `);
  const facts = h.json(`({seed:contractSeed,entry:contractEntry,fixture:contractFixture,initialMatch:contractInitial,
    steps:contractSteps,decisions:contractDecisions,duplicates:contractDuplicates,safety:contractSafety,
    finalState:contractFinalState,finalMatch:m,finalPlayer:contractFinalPlayer,restored:contractRestored,
    recordIntegrity:contractRecordIntegrity,saveRecordIntegrity:contractSaveRecordIntegrity,
    actualExposure:contractActualExposure,repeatedSettlement:{returns:contractRepeats,fullPlayerUnchanged:contractRepeatUnchanged},
    readsUnchanged:contractReadUnchanged,browserGlobals:typeof module==='undefined'&&typeof require==='undefined'})`);
  facts.hashes = { fixture: sha256(facts.fixture), initialMatch: sha256(facts.initialMatch), record: sha256(facts.finalMatch.gameRecord),
    log: sha256(facts.finalMatch.simulationLog), decisionSequence: sha256(facts.decisions) };
  facts.sources = { files: h.files, hashes: h.sourceHashes };
  // Read-only copies distinguish decision time, result time and final summary.
  facts.snapshots = { status: "KNOWN CONTRACT GAP", decisions: facts.decisions.map(d=>({
    id:d.choice.matchMomentId,decisionBefore:d.before,resultAfter:d.after,resolutionMoments:d.newCompleted,
    finalCompletedMoment:facts.finalMatch.completedMoments.find(x=>x.id===d.choice.matchMomentId)
  })), finalSummary: { inning:facts.finalMatch.inning,half:facts.finalMatch.half,outs:facts.finalMatch.outs,
    scores:facts.finalMatch.scores,runners:facts.finalMatch.runners,recordResult:facts.finalMatch.gameRecord.result } };
  return facts;
}
module.exports = { root, policy, sha256, createContext, playCanonicalMatch };

"use strict";
const assert = require("node:assert/strict");
const { policy, playCanonicalMatch } = require("./helpers/canonical-match-contract-context.cjs");

function runSuite() {
  let passed = 0;
  const executions = [], results = [];
  function check(title, fn) { fn(); passed += 1; console.log(`PASS ${title}`); }
  function validate(f, label) {
    const m=f.finalMatch, initial=f.initialMatch, log=m.simulationLog, side=f.entry.initialState.playerSide;
    const entries=log.filter(e=>e.type==='playerEntry'), entry=entries[0];
    const reached=log.filter(e=>e.type==='meaningfulMomentReached'), resolved=log.filter(e=>e.type==='meaningfulMomentResolved');
    const playerPAs=log.filter(e=>e.type==='plateAppearance'&&e.batterId==='player');
    check(`${label}: seed and browser-global owners`,()=>{
      assert.equal(m.simulationSeed,f.seed); assert.equal(f.entry.pendingSeedAfterPrepare,0); assert(f.browserGlobals);
      for(const value of Object.values(f.entry.globals)) assert.notEqual(value,'undefined');
      assert(!f.sources.files.includes('application-controller.js'));
    });
    check(`${label}: lawful entry, unchanged capability and Opportunity/roster agreement`,()=>{
      assert(f.entry.accepted); assert.equal(f.entry.age,16); assert(f.entry.invitationValidation.ok);
      assert(f.entry.capabilityValidation.ok); assert(f.entry.abilitiesUnchanged); assert.equal(f.entry.primaryPosition,'游擊手');
      assert.equal(f.entry.invitationIndex,policy.invitationIndex); assert.equal(f.entry.schoolId,'school-development-29d536a2');
      const exposure=initial.gameExposureState, opportunity=exposure.opportunitySnapshot;
      assert.equal(exposure.exposureSource,'opportunity-resolver'); assert(opportunity.decisionId);
      assert.equal(opportunity.assignedPosition,'游擊手'); assert.deepEqual(exposure.plannedUsage,opportunity.plannedUsage);
      assert.equal(exposure.plannedUsage.appearanceType,'lateGameAppearance'); assert.equal(exposure.plannedUsage.entryInning,6);
      assert.equal(initial.role,'starter'); assert.equal(initial.playerLineupStatus,'bench');
      assert.equal(initial.playerEntryCompleted,false); assert.equal(initial.playerLineupSlot,-1);
      assert(!initial.rosters[side].lineup.some(a=>a.id==='player')); assert(initial.rosters[side].bench.some(a=>a.id==='player'));
      assert(initial.rosters[side].teamRoster.players.some(a=>(a.playerId||a.id)==='player'));
    });
    check(`${label}: actual substitution precedes every player decision`,()=>{
      assert.equal(entries.length,1); assert.equal(entry.inning,initial.gameExposureState.plannedUsage.entryInning);
      assert.equal(entry.lineupSlot,7); assert.equal(m.playerLineupStatus,'substitute');
      assert.equal(m.rosters[side].lineup[entry.lineupSlot].id,'player'); assert.equal(f.finalState.actualSS,'player');
      for(const row of f.steps) for(const state of [row.before,row.after]) if(!state.entryCompleted) {
        assert(!state.playerInLineup); assert.deepEqual(state.completedIds,[]);
      }
      assert(reached.length>0); assert(reached.every(e=>e.sequence>entry.sequence));
      for(const d of f.decisions) {
        assert(d.before.entryCompleted&&d.before.playerInLineup); assert.equal(d.before.actualSS,'player');
        assert.equal(d.before.currentBatter,d.before.actualBatter);
        if(d.before.domain==='offense') { assert.equal(d.before.offenseTeam,side); assert.equal(d.before.actualBatter,'player'); }
      }
      assert(playerPAs.every(e=>e.sequence>entry.sequence));
    });
    check(`${label}: legal decisions each create one result and one completion`,()=>{
      assert(f.decisions.length>0); assert.equal(reached.length,f.decisions.length); assert.equal(resolved.length,f.decisions.length);
      assert.equal(m.completedMoments.length,f.decisions.length);
      assert.equal(new Set(m.completedMoments.map(x=>x.id)).size,m.completedMoments.length);
      for(const d of f.decisions) {
        assert(d.legalChoices.length>0); assert(d.legalChoices.some(c=>c.matchDecision===d.choice.matchDecision&&c.matchMomentId===d.choice.matchMomentId));
        const expected=d.legalChoices.find(c=>c.matchDecision==='secure'||c.matchDecision==='zone')||d.legalChoices[0];
        assert.deepEqual(d.choice,expected); assert.equal(d.sample,policy.sample); assert(d.returned);
        assert.equal(d.newCompleted.length,1); assert.equal(d.newCompleted[0].id,d.choice.matchMomentId);
        assert.equal(d.newCompleted[0].decision,d.choice.matchDecision);
        assert.equal(d.newEvents.filter(e=>e.type==='meaningfulMomentResolved').length,1);
        if(d.before.domain==='offense') assert.equal(d.newEvents.filter(e=>e.type==='plateAppearance'&&e.batterId==='player').length,1);
      }
      assert.equal(m.currentDomain,'complete'); assert.equal(m.activeSituation??null,null);
    });
    check(`${label}: natural full-match closure within original safety bound`,()=>{
      assert(m.completed&&m.settled); assert(f.safety<policy.safety); assert.equal(f.steps.length,f.safety);
      assert.equal(log.filter(e=>e.type==='gameEnd').length,1); assert.equal(m.half,'終'); assert.equal(m.outs,3);
    });
    check(`${label}: every playback/decision transition has valid Match State`,()=>{
      assert(f.steps.length>0); for(const row of f.steps) { assert.deepEqual(row.before.integrity,[]); assert.deepEqual(row.after.integrity,[]); }
      assert.deepEqual(f.finalState.integrity,[]);
    });
    check(`${label}: created/completed defense conservation (zero-coverage fixture)`,()=>{
      const count=m.completedMoments.filter(x=>x.domain==='defense').length;
      assert.equal(count,m.matchDecisionDensityState.defensiveMeaningfulDecisionCount); assert.equal(count,0);
    });
    check(`${label}: final Record agrees with score, totals, PA and event identities`,()=>{
      const r=m.gameRecord; assert.equal(r.status,'final'); assert.equal(f.recordIntegrity,true);
      for(const team of ['home','away']) {
        assert.equal(r.totals[team].runs,m.scores[team]); assert.equal(r.result.finalScore[team],m.scores[team]);
        assert.equal(r.inningLines.reduce((sum,line)=>sum+line[team==='home'?'homeRuns':'awayRuns'],0),m.scores[team]);
      }
      assert.equal(r.eventRefs.length,log.length); assert.equal(new Set(r.eventRefs.map(e=>e.eventId)).size,log.length);
      assert.deepEqual(r.eventRefs.map(e=>[e.sequence,e.type,e.inning,e.half]),log.map(e=>[e.sequence,e.type,e.inning,e.half]));
      assert.equal(r.playerLines.player.batting.PA,playerPAs.length);
      assert.equal(Object.values(r.playerLines).reduce((sum,line)=>sum+line.batting.PA,0),log.filter(e=>e.type==='plateAppearance').length);
    });
    check(`${label}: public resolve/settle/finish duplicates have no effects`,()=>{
      assert.equal(f.duplicates.length,f.decisions.length); for(const d of f.duplicates) { assert.equal(d.returned,false); assert(d.fullPlayerUnchanged); }
      assert.deepEqual(f.repeatedSettlement.returns,[false,false,false]); assert(f.repeatedSettlement.fullPlayerUnchanged); assert(f.readsUnchanged);
    });
    check(`${label}: Save memory round-trip retains Match, Record and Career`,()=>{
      const saved=f.restored; assert.equal(f.saveRecordIntegrity,true);
      for(const key of ['id','completed','settled','simulationSeed','scores','inning','half','outs','playerLineupStatus','playerEntryCompleted','rosters','gameRecord','simulationLog','completedMoments','gameExposureState','matchExperience'])
        assert.deepEqual(saved.highSchoolMatch[key],m[key],key);
      assert.deepEqual(saved.highSchoolCompetitionEvaluation,f.finalPlayer.highSchoolCompetitionEvaluation);
      assert.deepEqual(saved.highSchoolYearOneMatchHistory,f.finalPlayer.highSchoolYearOneMatchHistory);
    });
    check(`${label}: Career exposure agrees with real participation and settles once`,()=>{
      const a=f.actualExposure, exposure=m.gameExposureState, evaluation=f.finalPlayer.highSchoolCompetitionEvaluation;
      const defenseHalf=side==='home'?'上':'下';
      const innings=new Set(log.filter(e=>e.type==='halfInningEnd'&&e.half===defenseHalf&&e.sequence>=entry.sequence).map(e=>e.inning)).size;
      assert(a.participated); assert.equal(a.started,false); assert.equal(a.appearanceType,'lateGameAppearance');
      assert.equal(a.entryInning,entry.inning); assert.equal(a.exitInning,m.inning); assert.equal(a.plateAppearances,playerPAs.length); assert.equal(a.defensiveInnings,innings);
      assert(exposure.finalized); assert.equal(exposure.plateAppearances,playerPAs.length); assert.equal(exposure.defensiveInnings,innings);
      assert.equal(evaluation.sampleCount,1); assert.deepEqual(evaluation.appliedMatchIdentities,[m.id]);
      assert.equal(evaluation.exposureEvidence.started,false); assert.equal(evaluation.exposureEvidence.enteredGame,true);
      assert.equal(evaluation.exposureEvidence.plateAppearances,playerPAs.length); assert.equal(evaluation.exposureEvidence.defensiveInnings,innings);
      assert(m.matchExperience.settled); const history=f.finalPlayer.highSchoolYearOneMatchHistory;
      assert.equal(history.length,1); assert.equal(history[0].matchId,m.id);
      assert.deepEqual(history[0].actualExposure,{appearanceType:a.appearanceType,plateAppearances:a.plateAppearances,defensiveInnings:a.defensiveInnings,participated:a.participated});
    });
    check(`${label}: three snapshot times retained; KNOWN CONTRACT GAP disclosed`,()=>{
      assert.equal(f.snapshots.status,'KNOWN CONTRACT GAP'); assert.equal(f.snapshots.decisions.length,f.decisions.length);
      assert.equal(f.snapshots.finalSummary.inning,m.inning); assert.deepEqual(f.snapshots.finalSummary.scores,m.scores);
      for(const d of f.decisions) {
        const pa=d.newEvents.find(e=>e.type==='plateAppearance'&&e.batterId==='player');
        if(pa) { assert.equal(pa.before.outs,d.before.outs); assert.equal(pa.after.outs,d.after.outs); }
        assert.equal(d.newCompleted[0].inning,d.after.inning); assert.equal(d.newCompleted[0].half,d.after.half);
      }
      // This is a legacy gap witness, not acceptance of a decision snapshot.
      const last=f.snapshots.decisions.at(-1), result=last.resolutionMoments.at(-1), final=last.finalCompletedMoment;
      assert.notDeepEqual(result,final); assert.equal(final.inning,result.inning);
      assert.equal(final.half,'終'); assert.equal(final.outs,3); assert.deepEqual(final.scores,m.scores);
      assert.notEqual(final.inning,m.inning);
    });
  }
  for(const seed of policy.seeds) {
    const first=playCanonicalMatch(seed); executions.push({seed,run:'first',facts:first}); validate(first,`${seed}/first`);
    const replay=playCanonicalMatch(seed); executions.push({seed,run:'replay',facts:replay}); validate(replay,`${seed}/replay`);
    check(`${seed}: identical fresh-context replay Record/Log/Decision sequence`,()=>{
      assert.deepEqual(first.hashes,replay.hashes); assert.deepEqual(first.finalMatch.gameRecord,replay.finalMatch.gameRecord);
      assert.deepEqual(first.finalMatch.simulationLog,replay.finalMatch.simulationLog); assert.deepEqual(first.decisions,replay.decisions);
    });
    results.push({seed,status:'PASS',fixture:'legal sixth-inning SS substitute',runs:2,ticks:first.safety,score:first.finalMatch.scores,
      completedIds:first.finalMatch.completedMoments.map(x=>x.id),defenseCreated:first.finalMatch.matchDecisionDensityState.defensiveMeaningfulDecisionCount,
      defenseCompleted:first.finalMatch.completedMoments.filter(x=>x.domain==='defense').length,hashes:first.hashes,snapshot:'KNOWN CONTRACT GAP',replay:true});
  }
  const summary={suite:'canonical-match-regression',passed,failed:0,fullGames:executions.length,results,
    S3:'UNVERIFIED',SSStartingAdmission:'UNVERIFIED',nonzeroDefensiveMoment:'UNVERIFIED',snapshot:'KNOWN CONTRACT GAP',original36:'NOT EXECUTED / historical verdict unchanged'};
  console.log('CANONICAL_MATCH_REGRESSION_EVIDENCE='+JSON.stringify({policy,summary,executions}));
  console.log('CANONICAL_MATCH_REGRESSION_SUMMARY='+JSON.stringify(summary));
  console.log(`Canonical Match Regression: ${passed}/${passed} passed.`);
  return summary;
}
module.exports={runSuite};
if(require.main===module) runSuite();

"use strict";
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");
const { createRequire } = require("node:module");
const { createHash } = require("node:crypto");

// The original synthetic input includes artificial entry/phase and a completed
// Moment. It proves presentation only. No canonical fixture uses this context.
function runSuite() {
  const file=path.join(__dirname,'baseball-match-foundation-2-2-2-test.js');
  const source=fs.readFileSync(file,'utf8'), start=source.indexOf('verify("1.');
  const assertion=source.split(/\r?\n/).filter(line=>line.startsWith('verify("38.'));
  assert(start>0); assert.equal(assertion.length,1);
  const prefix=source.slice(0,start), rawIdentifiers=['hardGrounder','straightAtPlayer','playerRoutinePlay','selfCoverFirst','decisionTension'];
  for(const token of rawIdentifiers) assert(assertion[0].includes('"'+token+'"'));
  const outerModule={exports:{}};
  const observer=String.raw`
    vm.runInContext('globalThis.routineContractCalls=[];{const original=formatMatchSimulationEvent;formatMatchSimulationEvent=function(...args){const value=Reflect.apply(original,this,args);routineContractCalls.push(JSON.parse(JSON.stringify({event:args[0],formatted:value,seed:args[1].simulationSeed,playerAge:player.age,completedMoments:args[1].completedMoments})));return value;};}',context);
  `;
  const footer=String.raw`
    module.exports={passed,calls:JSON.parse(evaluate('JSON.stringify(routineContractCalls)'))};
  `;
  // Execute the exact original prefix and #38 line, without checks #1-37.
  vm.runInNewContext(prefix+observer+assertion[0]+'\n'+footer,
    {require:createRequire(file),__dirname,console,module:outerModule},{filename:'routine-commentary-original-38.cjs'});
  const result=outerModule.exports;
  assert.equal(result.passed,1); assert.equal(result.calls.length,1);
  const call=result.calls[0]; assert.equal(call.event.type,'playerRoutinePlay'); assert.equal(typeof call.formatted.text,'string'); assert(call.formatted.text.length>0);
  assert(!rawIdentifiers.some(raw=>call.formatted.text.includes(raw)));
  const summary={suite:'routine-commentary-contract',passedOriginalAssertions:result.passed,failed:0,
    originalAssertion:38,syntheticSimulationSeed:call.seed,text:call.formatted.text,
    rawIdentifiersAbsent:Object.fromEntries(rawIdentifiers.map(raw=>[raw,!call.formatted.text.includes(raw)])),canonicalAdmissionProof:false,fullMatchExecuted:false};
  console.log('ROUTINE_COMMENTARY_CONTRACT_EVIDENCE='+JSON.stringify({summary,originalTest:'tests/baseball-match-foundation-2-2-2-test.js',
    originalSourceSha256:createHash('sha256').update(Buffer.from(source)).digest('hex'),
    originalPrefixSha256:createHash('sha256').update(prefix).digest('hex'),originalAssertion:assertion[0],
    fixture:'Exact original __candidate2222 defaults, including legacy artificial setup',calls:result.calls}));
  console.log('ROUTINE_COMMENTARY_CONTRACT_SUMMARY='+JSON.stringify(summary));
  console.log('Routine Commentary Contract: 1/1 original assertion passed.');
  return summary;
}
module.exports={runSuite};
if(require.main===module) runSuite();

